From 94e868b650c9b9ab8651ccbbf8f1a63d08d9d8a0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:53:30 +0100
Subject: [PATCH] kded: let users choose which microphones push to talk
 controls

Push to talk always muted and unmuted every input device, so recording
from a capture card or loopback source while using it was not possible.
The Volume Controls page now lists the microphones to pick from.

BUG: 521697
---
 src/globalconfig.kcfg               |  3 +++
 src/kcm/ui/VolumeControlsConfig.qml | 25 +++++++++++++++++++++++++
 src/kded/audioshortcutsservice.cpp  | 14 +++++++++++++-
 src/kded/audioshortcutsservice.h    |  1 +
 4 files changed, 42 insertions(+), 1 deletion(-)

diff --git a/src/globalconfig.kcfg b/src/globalconfig.kcfg
index 29dd8626..5cc2b727 100644
--- a/src/globalconfig.kcfg
+++ b/src/globalconfig.kcfg
@@ -38,6 +38,9 @@
             <label>Show OSD when using push to talk.</label>
             <default>true</default>
         </entry>
+        <entry name="PushToTalkExcludedSources" type="StringList">
+            <label>Sources that push to talk does not mute and unmute.</label>
+        </entry>
         <entry name="MutedMicrophoneReminderOsd" type="Bool">
             <label>Show OSD when application starts using muted microphone.</label>
             <default>true</default>
diff --git a/src/kcm/ui/VolumeControlsConfig.qml b/src/kcm/ui/VolumeControlsConfig.qml
index 1e16d580..d743eeb0 100644
--- a/src/kcm/ui/VolumeControlsConfig.qml
+++ b/src/kcm/ui/VolumeControlsConfig.qml
@@ -110,6 +110,31 @@ Kirigami.Page {
                 onToggled: { config.defaultOutputDeviceOsd = checked; config.save() }
                 text: i18n("Default output device")
             }
+
+            Item {
+                Kirigami.FormData.isSection: true
+            }
+
+            Repeater {
+                model: SourceModel {}
+
+                QQC2.CheckBox {
+                    required property int index
+                    required property var model
+
+                    Kirigami.FormData.label: index === 0 ? i18nc("@label followed by a list of microphones", "Push to talk controls:") : ""
+                    text: model.Description || model.Name
+                    checked: !config.pushToTalkExcludedSources.includes(model.Name)
+                    onToggled: {
+                        const excluded = config.pushToTalkExcludedSources.filter(name => name !== model.Name);
+                        if (!checked) {
+                            excluded.push(model.Name);
+                        }
+                        config.pushToTalkExcludedSources = excluded;
+                        config.save();
+                    }
+                }
+            }
         }

         Item {
diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..16098334 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -443,6 +443,12 @@ void AudioShortcutsService::applyGlobalSourceMute(const QModelIndex &index, cons
     }
 }

+bool AudioShortcutsService::isPushToTalkExcluded(const QModelIndex &index) const
+{
+    const QString name = m_sourceModel->data(index, m_sourceModel->role("Name"_ba)).toString();
+    return m_globalConfig->pushToTalkExcludedSources().contains(name);
+}
+
 void AudioShortcutsService::handleNewSink(const QModelIndex &parent, int first, int last)
 {
     Q_UNUSED(parent)
@@ -506,6 +512,9 @@ void AudioShortcutsService::handleSourceDataChanged(const QModelIndex &topLeft,

     for (int i = topLeft.row(); i <= bottomRight.row(); ++i) {
         const auto index = m_sourceModel->index(i, 0);
+        if (isPushToTalkExcluded(index)) {
+            continue;
+        }

         const bool activePortIndexChanged = roles.contains(m_sourceModel->role("ActivePortIndex"_ba));
         const bool volumeChanged = roles.contains(m_sourceModel->role("Volume"_ba));
@@ -591,7 +600,10 @@ void AudioShortcutsService::pushToTalk(bool talk)
 {
     QStringList globalMicMuteMutedDevices = m_globalConfig->globalMuteSourcesMutedDevices();
     for (int i = 0; i < m_sourceModel->rowCount(); ++i) {
-        applyGlobalSourceMute(m_sourceModel->index(i, 0), !talk, globalMicMuteMutedDevices);
+        const auto index = m_sourceModel->index(i, 0);
+        if (!isPushToTalkExcluded(index)) {
+            applyGlobalSourceMute(index, !talk, globalMicMuteMutedDevices);
+        }
     }

     m_globalConfig->setGlobalMuteSourcesMutedDevices(globalMicMuteMutedDevices);
diff --git a/src/kded/audioshortcutsservice.h b/src/kded/audioshortcutsservice.h
index 26cf38d8..506e9d83 100644
--- a/src/kded/audioshortcutsservice.h
+++ b/src/kded/audioshortcutsservice.h
@@ -65,6 +65,7 @@ private:

     void applyGlobalSinkMute(const QModelIndex &index, const bool globalMute, QStringList &globalMuteMutedDevices);
     void applyGlobalSourceMute(const QModelIndex &index, const bool globalMute, QStringList &globalMuteMutedDevices);
+    bool isPushToTalkExcluded(const QModelIndex &index) const;
     void handleNewSink(const QModelIndex &parent, int first, int last);
     void handleNewSource(const QModelIndex &parent, int first, int last);
     void handleSinkDataChanged(const QModelIndex &topLeft, const QModelIndex &bottomRight, const QList<int> &roles);
-- 
